*******************************************************************			 ******	       Install		 ******	     Version 5.1		 ******	   March 3, 1989		 ******			 ******			 ******  This is the install routine for the patch to ROM 2.	 ******			 **************************************************************************************************************************************			 ******			 ******            Copyright (C) Apple Computer, Inc.	 ******            1985-1990		 ******            All Rights Reserved		 ******			 ******			 ************************************************************************************************************************************* Change History** 31 Mar 88	Steven Glass** Added code to install MiscTools patch.*** 02 Dec 88	Steven Glass*** Added SysBeep Patch to this file.** Patch to SysBeep** FixSysBeep.  This	routine copies the current contents of the* sysbeep vector to	a location below and substitues the a* address of a new routine.** NewSysBeep.  The new sysbeep checks to see if system volume* is set to 0 and if it is flashes the border instead of playing* any sound.** Code written by Steven Glass* 5 Feb 88** Change History** 21 Jun 88	Steven Glass** The WaitForVBL routine would wait forever if a VBL task* kept me from reading the counters in time.  So * we add a timeout counter.** 12 March 89	Steven Glass** Put machine size into new public variable:  BigMachine.** 30 Mar 89	Steven Glass** Added installation of IntMath patch.** 31 Mar 89	Steven Glass** Save the orig bell vector and put it in a public variable.** 18-Sep-90	Dave Lyons** Replaced PEA $A002 with an MMStartUp call to get our ID for* the UnloadSegNum call.  Our ID is apparently A002 or A003* depending on whether AppleTalk is around.** Added a store-zero to SchActive ($E01DDE).  This is already* in ROM 3, but nobody bothered putting it here.  (Without this* fix, after you crash in a scheduled task you never dispatch* any more until you power down!  Rebooting is not enough.)** 24-Sep-90	Dave Lyons** Crunched code by using a table instead of a bunch of _SetTSPtrs.** 25-Sep-90	Dave Lyons** Removed BigMachine support--we aren't trying to support 512K* machines anymore.** 16-Oct-90	Dave Lyons** Add JSL to AddTBNotifyProc (in Patch3:Locator.pch).** 20-Dec-90	Dave Lyons** Bring in Scheduler patch.** 16-Apr-91	Dave Lyons** Added JSL to AddTBRequestHandler (in Patch3:Locator.pch).** 17-Sep-91	Dave Lyons** Moved AddTBNotifyProc and AddTBRequestHandler to Tool.Setup.** 3-Jun-92	Dave Lyons** Check Battery RAM location $59; if bit 7 is set, call ROM to* install Visit Monitor and Memory Peeker CDAs, just like ROM 3* does.******************************************************************	blanks off	string asis	datachk off	include 'all.macros'	include ':::sys.equs.asm'Install	PROC	import TLCallTable	import MMCallTable	import DACallTable	import EMCallTable2	import ADBCallTable2	import Sane2CallTable	import SoundCallTable	import QDCallTable2	import FixSysBeep	import MTCallTable	import TTCallTable***	import BigMachine	import DAHandler	import MinRectToY1	import IMCallTable	import AddTBNotifyProc	;16-Oct-90 DAL	import SchedCallTable	;20-Dec-90 DAL	import AddTBRequestHandler	;16-Apr-91 DAL;---------------------------------------------------;; Added 18-Sep-90 DAL;; Zero out the SchActive flag at $E01DDE.  It's; really only a byte, but ROM 3 SchBootInit stores; zero over a word here, so we can do the same.;	lda #0	sta >$e01dde	;kill SchActive*** added 3-Jun-92 DAL -- Install Visit Monitor & Memory Peeker if***                       BRAM $59 bit 7 set (but $59 is not $FF)	pha	pea $0059	_ReadBParam	pla	sep #$30	inc a	beq @dontInstall	dec a	bpl @dontInstall	phk	per @return-1	pea $01C3-1	;RTL at $FF/01C3	jml >$ffa99f@return@dontInstall	rep #$30*** end 3-Jun-92** Do a bunch of SetTSPtrs from a table** New routine 24-Sep-90 DAL*	phb	phk	plb	ldx #0	;index into table@patch1tool	lda PatchTable+2,x	;flag word	bmi @done	phx	;keep index into table	pha	;push flag word	lda PatchTable,x	pha	;push toolset number	lda PatchTable+6,x	pha	;push high word of FPT	lda PatchTable+4,x	pha	;push low word of FPT	_SetTSPtr	pla	;retrieve index	clc	adc #8	tax	bra @patch1tool@done	plb*** added 8-Dec-91 DAL -- QDBootInit will point into space, so nuke it	lda #$0DDC-1	;$FE/0DDC is CLC, LDA #0000, RTL	sta >QDCallTable2+4	lda #$00FE	sta >QDCallTable2+6*** end 8-Dec-91	jsl FixSysBeep;;;	jsl AddTBNotifyProc		;16-Oct-90 DAL;;;	jsl AddTBRequestHandler	;16-Apr-91 DAL;---------------------------------------------------;; Now unload this segment of code be sure to do a jump instead; of a jsl this way we don't have to worry about whether this code; disappears...;;---------------------------------------------------	pha	; Added 18-Sep-90 DAL	_MMStartUp	;	plx	;	longa off	sep #$20	pla	ply	; get the return address from the stack***	pea $A002	; we know what our ID is!	phx	; No we don't!  DAL 18-Sep-90	pea $0001	; and our file num...	pea $0001	; even our segment number...	phy	pha	; put the return address back...	longa On	rep #$20	ldx #$0C11	; and make the unloadsegNumCall	jml >$E10000	; and call the tool locator...********************************************************************************** PatchTable** For each toolset to be patched, we have two Longs:**	dc.l $000x00tt,xxxCallTable** x is 1 if we need to do a "special" patch (tool 1 or 5 on ROM 3)* tt is the toolset number toopatch* xxxCallTable is the new call table**********************************************************************************PatchTable	dc.l $00000001,TLCallTable	dc.l $00000002,MMCallTable	dc.l $00000003,MTCallTable	dc.l $00000005,DACallTable	dc.l $00000006,EMCallTable2	dc.l $00000007,SchedCallTable	dc.l $00000009,ADBCallTable2	dc.l $0000000A,SANE2CallTable	dc.l $0000000B,IMCallTable	dc.l $00000008,SoundCallTable	dc.l $00000004,QDCallTable2	dc.l $0000000C,TTCallTable	dc.l $ffffffff	ENDP******************************************************************* FixSysBeep.** This routine copies the current contents of the* sysbeep vector to	a location below and substitues the a* address of NewSysBeep.** Change History** 14 Jul 88	Steven Glass** No longer save orig BellVector.** 31 Mar 89	Steven Glass** Okay, okay.  I'll save the orig vector.******************************************************************	EXPORT FixSysBeepFixSysBeep	PROC Export	import NewSysBeep	Import OrigBellVector		lda >BellVector	sta >OrigBellVector	lda >BellVector+2	sta >OrigBellVector+2	lda #NewSysBeep	sta >BellVector+1	lda #>NewSysBeep	sta >BellVector+2	rtl	EndP	END